/**
 * Page helpers for the specs: the manifest, calendar URLs, waiting until a page is stable enough to compare.
 *
 *   const {manifest, calendarPath, settle} = require('./lib/pages');
 *   await page.goto(calendarPath(manifest(), 'month', manifest().anchor));
 *   await settle(page);
 */
const fs = require('fs');
const os = require('os');
const path = require('path');
const { MANIFEST, FIREFOX_PDF } = require('./wp');

/**
 * The manifest of the content generated by this run (specs/content.setup.js).
 *
 * @returns {{anchor: string, timezone: string, pages: object,
 *     events: Object<string, {id: number, title: string, start: string}>}}
 */
function manifest() {
    return JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
}

/**
 * Path of a calendar view on a date.
 *
 * @param {object} m Manifest.
 * @param {string} view month, week, oneday or agenda.
 * @param {string} date Y-m-d.
 * @returns {string}
 */
function calendarPath(m, view, date) {
    return `${m.pages.calendar}action~${view}/exact_date~${date}/`;
}

/**
 * Waits until the page is laid out: no network activity, web fonts loaded, map tiles loaded (OpenStreetMap, over the
 * internet; decision N6: compared as they are), then a short settle for the calendar's scripts.
 *
 * @param {import('@playwright/test').Page} page
 * @param {{networkIdle?: boolean}} [options] networkIdle false for pages that never go quiet (the block editor polls).
 */
async function settle(page, { networkIdle = true } = {}) {
    if (networkIdle) {
        await page.waitForLoadState('networkidle');
    }
    await page.evaluate(() => document.fonts.ready);
    if (await page.locator('#osec-map').count()) {
        await page.waitForFunction(() => {
            const tiles = document.querySelectorAll('#osec-map .leaflet-tile');
            return tiles.length && [...tiles].every((tile) => tile.classList.contains('leaflet-tile-loaded'));
        }, null, { timeout: 20000 });
    }
    await page.waitForTimeout(300);
}

/**
 * Prints through the calendar's print button. The button's handler builds the print page, calls window.print() and
 * restores the page when it returns; the stub throws, so the print page stays. Then print media is emulated. The
 * real window.print stays available as window.osecRealPrint (firefoxPdf()).
 *
 * @param {import('@playwright/test').Page} page
 */
async function printView(page) {
    await page.evaluate(() => {
        window.osecRealPrint = window.print;
        window.print = () => {
            throw new Error('osec print stub');
        };
    });
    await page.locator('#ai1ec-print-button').first().click();
    await page.emulateMedia({ media: 'print' });
    await settle(page);
}

/**
 * The PDF of the page's current state, printed by Firefox (after printView()): the real window.print() saves it
 * silently inside the playwright container (prefs in lib/wp.js), and opening that file starts a download Playwright
 * hands to this process. The file keeps the previous print until the new one is written, so the content is read
 * before printing and polled until it changed.
 *
 * @param {import('@playwright/test').Page} page
 * @returns {Promise<Buffer>}
 * @throws {Error} When no new PDF appears within 15 s.
 */
async function firefoxPdf(page) {
    const before = await readFirefoxPdf(page.context());
    await page.evaluate(() => window.osecRealPrint.call(window));
    for (let waited = 0; waited < 15000; waited += 500) {
        await page.waitForTimeout(500);
        const pdf = await readFirefoxPdf(page.context());
        if (pdf && pdf.length && (!before || !pdf.equals(before))) {
            return pdf;
        }
    }
    throw new Error(`Firefox wrote no new PDF to ${FIREFOX_PDF} within 15 s.`);
}

/**
 * Current content of FIREFOX_PDF, fetched as a download, or null when there is none yet.
 *
 * @param {import('@playwright/test').BrowserContext} context
 * @returns {Promise<Buffer|null>}
 */
async function readFirefoxPdf(context) {
    const viewer = await context.newPage();
    const file = path.join(os.tmpdir(), `osec-firefox-${process.pid}-${Date.now()}.pdf`);
    try {
        const download = viewer.waitForEvent('download', { timeout: 5000 });
        // A file Firefox does not display starts a download; a missing one fails with NS_ERROR_FILE_NOT_FOUND.
        const missing = await viewer.goto(`file://${FIREFOX_PDF}`).then(() => false, (e) => !/Download is starting/.test(e.message));
        if (missing) {
            download.catch(() => {});
            return null;
        }
        await (await download).saveAs(file);
        return fs.readFileSync(file);
    } finally {
        fs.rmSync(file, { force: true });
        await viewer.close();
    }
}

/**
 * Compares a page or element with its baseline (toHaveScreenshot) and records what the review page
 * (lib/review-reporter.js) shows: the baseline's name, and for a passing test the current shot (Playwright keeps
 * actual and diff images of failed comparisons only). A failed comparison still fails the test.
 *
 *   await compareShot(page.locator('main'), [theme, 'month-1280.png']);
 *   await compareShot(page, ['admin-events.png'], {fullPage: true});
 *
 * @param {import('@playwright/test').Page|import('@playwright/test').Locator} target
 * @param {string[]} name Snapshot name segments, as for toHaveScreenshot().
 * @param {object} [options] toHaveScreenshot() options (fullPage for pages).
 */
async function compareShot(target, name, options = {}) {
    // Required here, not at the top: bin/screenshots/shoot.js uses settle() with its own @playwright/test, and
    // Playwright refuses to be loaded from two node_modules folders.
    const { test, expect } = require('@playwright/test');
    const testInfo = test.info();
    await testInfo.attach('osec-review', {
        body: JSON.stringify({ name }),
        contentType: 'application/json',
    });
    // A failed comparison throws here; Playwright attaches expected, actual and diff itself.
    await expect(target).toHaveScreenshot(name, options);
    // Passed: the current shot as the comparison took it (same settings as the config's toHaveScreenshot).
    const shot = await target.screenshot({
        animations: 'disabled',
        caret: 'hide',
        ...(options.fullPage ? { fullPage: true } : {}),
    });
    await testInfo.attach('osec-current', {
        body: shot,
        contentType: 'image/png',
    });
}

/**
 * Test details for the HTML report: a description, shown under the test's title.
 *
 *   test('Month view', about('What the test checks and why.'), async ({page}) => { ... });
 *
 * @param {string} description
 * @returns {{annotation: {type: string, description: string}}}
 */
function about(description) {
    return {
        annotation: {
            type: 'description',
            // A long description spans lines inside its template literal: one line in the report.
            description: description.replace(/\s+/g, ' ').trim(),
        },
    };
}

/**
 * Replaces values that change from run to run with a visible marker, so the shot stays comparable and nobody mistakes
 * the marker for real output: the text becomes "<label (replaced by test)>" in red. Every replacement in a shot goes
 * through here and is listed where the screen is defined (screens.js `replace`); never hide or blank such a value
 * silently. Fails when an entry finds nothing, so a renamed element cannot turn a replacement into a no-op.
 *
 * @param {import('@playwright/test').Page} page
 * @param {Array<{label: string, selector: string, text?: string, target?: string, pattern?: string}>} replacements
 *     `selector` finds the element, `text` (optional) the start of its text that picks it among several, `target`
 *     (optional) a child of it whose text is replaced instead of the whole element, `pattern` (optional, a regular
 *     expression source) only the matching parts of its text, every match, e.g. the site address in a permalink; the
 *     rest stays. `label` names the value in the marker.
 */
async function replaceForShot(page, replacements = []) {
    for (const { label, selector, text, target, pattern } of replacements) {
        const count = await page.evaluate(({
            label: name, selector: css, text: start, target: child, pattern: source,
        }) => {
            const marker = `<${name} (replaced by test)>`;
            const found = [...document.querySelectorAll(css)]
                .filter((element) => !start || element.textContent.trim().startsWith(start))
                .map((element) => (child ? element.querySelector(child) : element))
                .filter(Boolean);
            if (!source) {
                found.forEach((element) => {
                    element.textContent = marker;
                    element.style.color = 'red';
                });
                return found.length;
            }
            // Every matching part of the text becomes the marker, in a red span of its own; the rest stays.
            let replaced = 0;
            const expression = new RegExp(source, 'g');
            found.forEach((element) => {
                const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
                const nodes = [];
                for (let node = walker.nextNode(); node; node = walker.nextNode()) {
                    nodes.push(node);
                }
                nodes.forEach((node) => {
                    const matches = [...node.nodeValue.matchAll(expression)].filter((match) => match[0]);
                    if (!matches.length) {
                        return;
                    }
                    const parts = document.createDocumentFragment();
                    let last = 0;
                    matches.forEach((match) => {
                        parts.append(node.nodeValue.slice(last, match.index));
                        const span = document.createElement('span');
                        span.textContent = marker;
                        span.style.color = 'red';
                        parts.append(span);
                        last = match.index + match[0].length;
                    });
                    parts.append(node.nodeValue.slice(last));
                    node.replaceWith(parts);
                    replaced += matches.length;
                });
            });
            return replaced;
        }, {
            label,
            selector,
            text,
            target,
            pattern,
        });
        if (!count) {
            throw new Error(`replaceForShot: "${label}" not found (${selector}${text ? `, text "${text}"` : ''}${
                pattern ? `, pattern ${pattern}` : ''})`);
        }
    }
}

module.exports = {
    manifest,
    calendarPath,
    settle,
    printView,
    firefoxPdf,
    compareShot,
    replaceForShot,
    about,
};
